 {Policy p;assert(p.Admit(owner,50));auto real=Start(p,owner,Work::Renderer,21,"",10);assert(real&&p.CaptureSubmitted(owner));assert(p.Cancel(owner,"ACTUAL_OWNER_ABORT",12)&&p.CleanupClosed(owner));assert(p.Physical()==1&&p.Ready(owner,12)==Outcome::Pending);assert(!p.Retire(owner,12));assert(p.Acknowledge(*real,true,"",60)&&p.Ready(owner,60)==Outcome::Canceled);assert(p.Get(owner)->error=="ACTUAL_OWNER_ABORT");++groups;}
