 {Policy p;assert(p.Admit(owner,50));auto real=Start(p,owner,Work::Renderer,21,"",10);assert(real&&p.CaptureSubmitted(owner));assert(p.Fail(owner,"ACTUAL_CONTEXT_LOSS",20)&&p.CleanupClosed(owner));assert(p.Acknowledge(*real,true,"",55)&&p.Validated(owner)&&p.Ready(owner,55)==Outcome::HardFailure);assert(p.Get(owner)->error=="ACTUAL_CONTEXT_LOSS");++groups;}
 {Policy p;assert(p.Admit(owner,50)&&p.Observe(owner,10)&&p.Freeze(owner,true,11)&&p.CleanupClosed(owner));assert(p.Ready(owner,12)==Outcome::Passed);assert(p.Ready(owner,50)==Outcome::HardFailure);++groups;}
 {Policy p;assert(p.Admit(owner,50)&&p.Observe(owner,10));assert(p.Freeze(owner,true,50)&&p.CleanupClosed(owner)&&p.Ready(owner,50)==Outcome::HardFailure);assert(p.Get(owner)->error.find("publication")!=std::string::npos);++groups;}
 {Policy p;assert(p.Admit(owner,0)&&p.Observe(owner,10)&&p.Freeze(owner,true,1e12)&&p.CleanupClosed(owner));assert(p.Ready(owner,1e12)==Outcome::Passed);++groups;}
 {Policy p;assert(p.Admit(owner,50));auto renderer=Start(p,owner,Work::Renderer,21,"",10),pixels=Start(p,owner,Work::Pixels,0,"",11);assert(renderer&&pixels);p.ChannelClosed(3,12);assert(p.Physical()==1&&p.Ready(owner,12)==Outcome::Pending);assert(p.Acknowledge(*pixels,true,"",15)&&p.Ready(owner,15)==Outcome::HardFailure);assert(!p.Acknowledge(*renderer,true,"",16));++groups;}
 {Policy p;assert(p.Admit(owner,50));auto real=Start(p,owner,Work::Renderer,21,"",10);assert(real);assert(p.Cancel(owner,"ACTUAL_CALLBACK_CLOSED",11)&&p.CleanupClosed(owner));assert(!p.Admit({3,7,12},50));assert(p.Acknowledge(*real,true,"",12)&&p.Retire(owner,12));assert(p.Admit({3,7,12},50)&&!p.Acknowledge(*real,true,"",13));++groups;}
