 {Policy p;assert(p.Admit(owner,50)&&p.Freeze(owner,false,50));assert(!p.Watchdog(owner,2049)&&p.Watchdog(owner,2050)&&!p.Watchdog(owner,2051));assert(!Start(p,owner,Work::Restoration,21,"",2050));++groups;}
 {Policy p;for(int n=1;n<=16;++n)assert(p.Admit({3,n,uint64_t(n)},50));assert(!p.Admit({3,17,17},50));for(int n=1;n<=128;++n)assert(Start(p,{3,1,1},Work::Renderer,n,"",10));assert(!Start(p,{3,1,1},Work::Renderer,129,"",10)&&p.Physical()==128);p.ChannelClosed(3,11);assert(!p.Physical());++groups;}
 {Policy p;assert(p.Admit(owner,50));auto planned=Start(p,owner,Work::Cleanup,0,"",1),view=Start(p,owner,Work::View,0,"",1),files=Start(p,owner,Work::Files,0,"",1);assert(planned&&view&&files&&p.Physical(owner,Work::View)==1);p.ChannelClosed(3,10);assert(p.Physical()==1&&p.Physical(owner,Work::Files)==1);assert(!p.Acknowledge(*planned,true,"",11)&&!p.Acknowledge(*view,true,"",11));assert(p.Acknowledge(*files,true,"",11)&&p.Ready(owner,11)==Outcome::HardFailure);++groups;}
 {Policy p;assert(p.Admit(owner,50));auto reserved=p.Begin(owner,Work::Renderer,21,"",1);assert(reserved&&!p.Acknowledge(*reserved,true,"",2)&&p.WithdrawUnsubmitted(*reserved)&&!p.Physical());reserved=p.Begin(owner,Work::Renderer,22,"",3);assert(reserved&&p.EnterSubmission(*reserved)&&!p.WithdrawUnsubmitted(*reserved)&&p.Physical()==1);assert(p.Acknowledge(*reserved,true,"",4)&&!p.Physical());++groups;}
